import{_ as e}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as a,c as n,ak as r}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.CCsCLXn2.webp",s="/projects/esp32Sensor/en/latest/assets/2.C8c07uFL.webp",l="/projects/esp32Sensor/en/latest/assets/3.04spv1O7.webp",d="/projects/esp32Sensor/en/latest/assets/4.DjhaZFNS.webp",y=JSON.parse('{"title":"2. Button Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Button Module.md","filePath":"docs/2. Button Module.md"}'),c={name:"docs/2. Button Module.md"};function h(u,t,p,m,g,b){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_2-button-module" tabindex="-1">2. Button Module <a class="header-anchor" href="#_2-button-module" aria-label="Permalink to &quot;2. Button Module&quot;">​</a></h1><h2 id="_2-1-introduction" tabindex="-1">2.1 Introduction <a class="header-anchor" href="#_2-1-introduction" aria-label="Permalink to &quot;2.1 Introduction&quot;">​</a></h2><p>The button module comes equipped with a white button cap and is widely used across various maker DIY projects, including environmental monitoring systems, electronic scales, robot cars, and robotics.</p><img loading="lazy" height="1156" width="1156" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_2-2-technical-specifications" tabindex="-1">2.2 Technical Specifications <a class="header-anchor" href="#_2-2-technical-specifications" aria-label="Permalink to &quot;2.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Trigger mode</td><td style="text-align:center;">Press-to-trigger</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 24.0 mm</td></tr></tbody></table><h2 id="_2-3-hands-on-project" tabindex="-1">2.3 Hands-On Project <a class="header-anchor" href="#_2-3-hands-on-project" aria-label="Permalink to &quot;2.3 Hands-On Project&quot;">​</a></h2><h3 id="_2-3-1-project-overview" tabindex="-1">2.3.1 Project Overview <a class="header-anchor" href="#_2-3-1-project-overview" aria-label="Permalink to &quot;2.3.1 Project Overview&quot;">​</a></h3><p>This project uses the button module and the onboard buzzer of the controller to implement a push-button doorbell. When the button module is pressed, the buzzer plays note C5 in the background. Once the button is released, the buzzer stops immediately, demonstrating button signal acquisition and conditional branch logic.</p><h3 id="_2-3-2-hardware-wiring" tabindex="-1">2.3.2 Hardware Wiring <a class="header-anchor" href="#_2-3-2-hardware-wiring" aria-label="Permalink to &quot;2.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the button module to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="621" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_2-3-3-adding-extensions" tabindex="-1">2.3.3 Adding Extensions <a class="header-anchor" href="#_2-3-3-adding-extensions" aria-label="Permalink to &quot;2.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Button sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_2-3-4-complete-program-and-analysis" tabindex="-1">2.3.4 Complete Program and Analysis <a class="header-anchor" href="#_2-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;2.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the status of the button module connected to port P5 is continuously monitored to determine whether the button is pressed:</p><ul><li><p>When the button is pressed, the buzzer plays note C5 continuously in the background.</p></li><li><p>When the button is released, the buzzer turns off, stopping sound output.</p></li></ul></li><li><p>A 0.1 s delay is executed at the end of each loop iteration before repeating the entire button detection process.</p></li></ol><img loading="lazy" height="428" width="678" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/02 Button Module.sb3</a>.</strong></p></div><h3 id="_2-3-5-program-upload" tabindex="-1">2.3.5 Program Upload <a class="header-anchor" href="#_2-3-5-program-upload" aria-label="Permalink to &quot;2.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_2-3-6-program-outcome" tabindex="-1">2.3.6 Program Outcome <a class="header-anchor" href="#_2-3-6-program-outcome" aria-label="Permalink to &quot;2.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, pressing the button module connected to port P5 triggers the buzzer to play note C5. Releasing the button module immediately silences the buzzer, delivering an interactive doorbell response.</p>',25)])])}const x=o(c,[["render",h]]);export{y as __pageData,x as default};
